hw({id:'wp-transfer',t:'word',k:['saq','long'],p:1,lv:2,make(k){const [A,B]=hwN(2),kk=R(2,5),Bp=R(15,80),g=R(10,60),D=(kk-1)*Bp-2*g;if(D<=5)return null;const v=Bp+g,it=pick(['stickers','marbles','cards']);
  const q={stem:`${A} had ${D} more ${it} than ${B} at first. ${B} gave ${A} ${g} ${it}. In the end, ${A} had ${kk} times as many ${it} as ${B}. How many ${it} did ${B} have at first?`,
    parts:[hwNum(v,{marks:k==='long'?3:2,traps:[[(D+g)/(kk-1)+g,`When ${B} gives ${g} away and ${A} gets ${g}, the difference grows by ${g} × 2.`],[Bp,`That is how many ${B} had in the END.`],[(D-2*g)/(kk-1)+g,'The difference got BIGGER, not smaller.']],work:[`New difference: ${D} + ${g} + ${g} = ${D+2*g}`,`In the end ${A} has ${kk} units and ${B} has 1 unit, so ${kk-1} units = ${D+2*g}, 1 unit = ${Bp}`,`${B} at first: ${Bp} + ${g} = <b>${v}</b>`],hint:'Draw before-and-after bars. How does the difference change?'})]};
  q.cal={lines:[`New difference: ${D} + ${g} = ${D+g}`,`${kk-1} units = ${D+g}`,`…`],bad:0,why:`${B} LOSES ${g} and ${A} GAINS ${g}, so the gap grows by ${2*g}, not ${g}.`,fix:`New difference: ${D} + ${g} + ${g} = ${D+2*g}`};if(!hwInt((D+g)/(kk-1)))q.cal=null;else q.cal.lines[2]=`1 unit = ${(D+g)/(kk-1)}, so ${B} had ${(D+g)/(kk-1)+g} at first.`;return q}});
hw({id:'wp-same',t:'word',k:['saq'],p:1,lv:2,make(){const [A,B]=hwN(2),kk=R(2,6),x=R(20,100),Bp=R(10,40);const y=(kk-1)*Bp-x;if(y<=4)return null;const v=kk*Bp;
  return {stem:`${A} and ${B} had the same length of ribbon at first. ${A} bought another ${x} cm of ribbon and ${B} used ${y} cm of ribbon. In the end, ${A} had ${kk} times as much ribbon as ${B}. What length of ribbon did ${A} have in the end?`,parts:[hwNum(v,{unit:'cm',traps:[[Bp,`That is ${B}'s ribbon in the end.`],[(x-y)/(kk-1)*kk,'The gap between them is '+x+' + '+y+', not '+x+' − '+y+'.']],work:[`Gap in the end: ${x} + ${y} = ${x+y} cm`,`${kk} units − 1 unit = ${kk-1} units = ${x+y}, so 1 unit = ${Bp} cm`,`${A}: ${kk} × ${Bp} = <b>${v} cm</b>`],hint:'They started the same. How far apart are they at the end?'})]}}});
hw({id:'wp-short',t:'word',k:'long',p:2,lv:2,make(){const nm=hwN()[0],p=R(18,95)/10,n1=R(5,9),n2=R(1,n1-2),s=R(5,40)/10,l=r6(p*(n1-n2)-s);if(l<=0)return null;const M=r6(n2*p+l),it=pick(['pens','notebooks','files','bowls of noodles']);
  return {stem:`${nm} wanted to buy ${n1} ${it} but was short of ${$m(s)}. Instead, ${nm} bought ${n2} ${it} and had ${$m(l)} left.`,
    parts:[hwNum(p,{q:'What was the cost of one?',marks:2,pre:'$',traps:[[r6((l-s)/(n1-n2)),`Short of ${$m(s)} plus ${$m(l)} left: the ${n1-n2} ${it} cost ${$m(s)} + ${$m(l)}.`],[r6((s+l)/n1),`The difference is ${n1-n2} ${it}.`]],work:[`${n1} − ${n2} = ${n1-n2} ${it} cost ${$m(s)} + ${$m(l)} = ${$m(s+l)}`,`One costs ${$m(s+l)} ÷ ${n1-n2} = <b>${$m(p)}</b>`],hint:`What is the difference between the two plans?`}),
      hwNum(M,{q:`How much money did ${nm} have?`,marks:1,pre:'$',traps:[[r6(n1*p),`${nm} was SHORT for ${n1} ${it}.`]],work:[`${n2} × ${$m(p)} + ${$m(l)} = <b>${$m(M)}</b>`]})]}}});
hw({id:'wp-assume',t:'word',k:'long',p:2,lv:2,make(){if(Math.random()<.5){const N=R(20,60),f=R(5,N-5),v=r6((N-f)*.2+f*.5),nm=hwN()[0];
    return {stem:`${nm} has ${N} coins. Each coin is either a 20-cent coin or a 50-cent coin. The total value of the coins is ${$m(v)}.`,parts:[hwNum(f,{q:'How many 50-cent coins are there?',marks:3,unit:'coins',traps:[[N-f,'That is the number of 20-cent coins.'],[Math.round((v-N*.2)/.5),'Each swap from a 20¢ coin to a 50¢ coin adds 30¢, not 50¢.']],work:[`If all were 20¢: ${N} × $0.20 = ${$m(N*.2)}`,`Extra: ${$m(v)} − ${$m(N*.2)} = ${$m(v-N*.2)}. Each 50¢ coin adds $0.30.`,`${$m(v-N*.2)} ÷ $0.30 = <b>${f}</b>`],hint:'Assume they are all 20-cent coins. How much is missing?'}),
      hwNum(r6(f*.5-(N-f)*.2),{q:'How much more is the value of the 50-cent coins than the 20-cent coins?',marks:1,pre:'$',neg:true,traps:[],work:[`50¢: ${f} × $0.50 = ${$m(f*.5)}; 20¢: ${N-f} × $0.20 = ${$m((N-f)*.2)}`,`Difference: <b>${$m(Math.abs(f*.5-(N-f)*.2))}</b>`]})].filter(p=>p.v>0)}}
  const N=pick([200,250,300,400]),a=pick([40,50,60]),b=pick([20,25,30]),sp=R(5,40),T=(N-sp)*a-sp*b;
  return {stem:`A bakery delivered ${N} cakes to a hotel. The hotel paid ${$m(a)} for each cake in good condition. For every spoilt cake, the bakery had to pay the hotel ${$m(b)}. The bakery received ${$m(T)} altogether.`,parts:[hwNum(sp,{q:'How many cakes were spoilt?',marks:3,unit:'cakes',traps:[[(N*a-T)/a,`Each spoilt cake costs the bakery ${$m(a)} (not paid) + ${$m(b)} (penalty).`],[N-sp,'That is the number of good cakes.']],work:[`If all were good: ${N} × ${$m(a)} = ${$m(N*a)}`,`Shortfall: ${$m(N*a)} − ${$m(T)} = ${$m(N*a-T)}. Each spoilt cake loses ${$m(a)} + ${$m(b)} = ${$m(a+b)}.`,`${$m(N*a-T)} ÷ ${$m(a+b)} = <b>${sp}</b>`],hint:'Assume all the cakes were good. How much less did the bakery get?'})]}}});
hw({id:'wp-equal',t:'word',k:'long',p:2,lv:3,make(){if(Math.random()<.5){const [g1,g2]=pick([[5,3],[4,3],[3,2],[4,5]]),c1=R(25,60)/10,c2=R(30,80)/10,L=lcm(g1,g2),per1=L/g1*c1,per2=L/g2*c2,diff=r6(per2-per1);if(diff<=0)return null;const grp=R(4,15),X=r6(diff*grp),n=L*grp;
    return {stem:`Apples were sold at ${g1} for ${$m(c1)} and pears at ${g2} for ${$m(c2)}. Mr Lee bought an equal number of apples and pears. He spent ${$m(X)} more on pears than on apples.`,parts:[hwNum(n,{q:'How many apples did he buy?',marks:3,traps:[[grp,`That is the number of groups of ${L}. Each group has ${L} apples.`],[Math.round(X/(c2-c1)),`The prices are for different numbers of fruit. Use groups of ${L}.`]],work:[`Use groups of ${L} (the LCM of ${g1} and ${g2}).`,`${L} apples cost ${$m(per1)}; ${L} pears cost ${$m(per2)}. Difference per group: ${$m(diff)}`,`${$m(X)} ÷ ${$m(diff)} = ${grp} groups → ${grp} × ${L} = <b>${n}</b> apples`],hint:`Find a number of fruit that works for both deals: ${g1} and ${g2} → ${L}.`}),
      hwNum(r6(grp*(per1+per2)),{q:'How much did he spend altogether?',marks:1,pre:'$',traps:[],work:[`${grp} × (${$m(per1)} + ${$m(per2)}) = <b>${$m(grp*(per1+per2))}</b>`]})]}}
  const [g1,g2]=pick([[4,7],[3,5],[4,6],[5,8]]),c1=pick([3,2.5,4]),c2=pick([5,4.5,6]),L=lcm(g1,g2),gc=L/g1*c1+L/g2*c2,grp=R(2,8),T=r6(gc*grp);
  return {stem:`Muffins were sold at ${g1} for ${$m(c1)} and tarts at ${g2} for ${$m(c2)}. Sandy bought an equal number of muffins and tarts and paid ${$m(T)} altogether.`,parts:[hwNum(2*L*grp,{q:'How many muffins and tarts did she buy altogether?',marks:3,traps:[[L*grp,'That is only the muffins (or only the tarts).'],[grp*(g1+g2),`The deals use different numbers of items. Use groups of ${L}.`]],work:[`Groups of ${L} muffins and ${L} tarts cost ${L/g1} × ${$m(c1)} + ${L/g2} × ${$m(c2)} = ${$m(gc)}`,`${$m(T)} ÷ ${$m(gc)} = ${grp} groups`,`${grp} × ${2*L} = <b>${2*L*grp}</b>`],hint:`Make a group with the same number of each: ${L}.`})]}}});
hw({id:'wp-boxes',t:'word',k:'long',p:2,lv:3,make(){const nm=hwN()[0],a=R(4,6),b=a+R(1,3),n=R(8,20),s=R(60,120),h=s-R(5,25);const e=(h-s)+n*(b-a);if(e<=0)return null;
  return {stem:`${nm} had ${s} star stickers and ${h} heart stickers. Then ${nm} bought the same number of boxes of each. Each box of star stickers had ${a} stickers and each box of heart stickers had ${b} stickers. In the end, there were ${e} more heart stickers than star stickers.`,
    parts:[hwNum(n,{q:'How many boxes of star stickers did '+nm+' buy?',marks:3,unit:'boxes',traps:[[e/(b-a),`At first there were ${s-h} MORE stars. The hearts had to catch up first.`],[(e+s-h)/b,'Each pair of boxes closes the gap by '+(b-a)+'.']],work:[`At first, stars were ahead by ${s} − ${h} = ${s-h}.`,`Each pair of boxes adds ${b-a} more heart${b-a>1?"s":""} than stars. To end ${e} ahead, the hearts gain ${s-h} + ${e} = ${s-h+e}.`,`${s-h+e} ÷ ${b-a} = <b>${n}</b> boxes`],hint:'Each time a box of each is bought, how much does the gap change?'}),
      hwNum(s+h+n*(a+b),{q:'How many stickers were there in the end altogether?',marks:1,traps:[[s+h,'Add the stickers in the boxes.']],work:[`${s} + ${h} + ${n} × (${a} + ${b}) = <b>${s+h+n*(a+b)}</b>`]})]}}});
hw({id:'wp-two',t:'word',k:['saq'],p:2,lv:2,make(){const T=R(0,2);
  if(T===0){const b=R(50,120)/10,pn=R(10,40)/10,x=pick([3,2,4]),y=pick([4,5,3]);if(x===y)return null;const T1=r6(x*b+y*pn),T2=r6(b+pn);if(y<=x)return null;
    return {stem:`${x} identical books and ${y} identical pens cost ${$m(T1)}. One book and one pen cost ${$m(T2)}. How much does each pen cost?`,parts:[hwNum(pn,{pre:'$',traps:[[b,'That is the cost of a book.'],[r6(T1-T2),'Take away '+x+' sets of (book + pen), not one.']],work:[`${x} books + ${x} pens = ${x} × ${$m(T2)} = ${$m(x*T2)}`,`${y-x} pen${y-x>1?'s':''} = ${$m(T1)} − ${$m(x*T2)} = ${$m(T1-x*T2)}`,`1 pen = <b>${$m(pn)}</b>`],hint:`Make the books the same: ${x} sets of (1 book + 1 pen).`})]}}
  if(T===1){const f=R(50,150)/10,pn=R(10,90)/10,T1=r6(f+3*pn),T2=r6(2*f+8*pn);return {stem:`A file and 3 identical pens cost ${$m(T1)}. 2 such files and 8 such pens cost ${$m(T2)}. What is the cost of 1 pen?`,parts:[hwNum(pn,{pre:'$',traps:[[r6((T2-T1)/5),'Double the first line first so the files match.'],[f,'That is the cost of a file.']],work:[`Double the first: 2 files + 6 pens = ${$m(2*T1)}`,`2 pens = ${$m(T2)} − ${$m(2*T1)} = ${$m(T2-2*T1)}`,`1 pen = <b>${$m(pn)}</b>`],hint:'Make the number of files the same.'})]}}
  const bk=R(3,9),pn=R(1,5),T1=5*bk+2*pn,T2=2*bk+5*pn;return {stem:`Sarah paid ${$m(T1)} for 5 books and 2 pens. Tanya paid ${$m(T2)} for 2 books and 5 pens. All the books cost the same and all the pens cost the same. Find the cost of 1 book and 1 pen together.`,parts:[hwNum(bk+pn,{pre:'$',traps:[[T1+T2,'That is 7 books and 7 pens.'],[(T1+T2)/2,'Together they bought 7 books and 7 pens.']],work:[`Together: 7 books + 7 pens = ${$m(T1)} + ${$m(T2)} = ${$m(T1+T2)}`,`1 book + 1 pen = ${$m(T1+T2)} ÷ 7 = <b>${$m(bk+pn)}</b>`],hint:'Add the two purchases. What do you notice?'})]}}});
hw({id:'wp-save',t:'word',k:'long',p:2,lv:3,make(){const [A,B]=hwN(2),a=pick([.5,.6,.8,1]),b=r6(a+pick([.2,.3,.4,.5])),d=R(5,15),t=R(10,40),e=r6(b*t-a*(d+t));if(e<=0||!hwInt(e*10))return null;
  return {stem:`${A} saves ${$m(a)} every day. ${B} saves ${$m(b)} every day. ${B} started saving ${d} days after ${A}.`,parts:[hwNum(t,{q:`How many days after starting will ${B} have saved ${$m(e)} more than ${A}?`,marks:3,unit:'days',traps:[[r6(e/(b-a)),`${A} was already ${$m(a*d)} ahead when ${B} started.`],[t+d,`Count from when ${B} started.`]],work:[`When ${B} starts, ${A} has ${d} × ${$m(a)} = ${$m(a*d)}.`,`Each day ${B} catches up ${$m(b-a)}. ${B} must gain ${$m(a*d)} + ${$m(e)} = ${$m(a*d+e)}.`,`${$m(a*d+e)} ÷ ${$m(b-a)} = <b>${t}</b> days`],hint:`How far ahead is ${A} when ${B} starts?`}),
    hwNum(r6(a*(d+t)+b*t),{q:'How much will they have saved altogether by then?',marks:1,pre:'$',traps:[],work:[`${A}: ${d+t} × ${$m(a)} = ${$m(a*(d+t))}; ${B}: ${t} × ${$m(b)} = ${$m(b*t)}`,`Total: <b>${$m(a*(d+t)+b*t)}</b>`]})]}}});
hw({id:'wp-fruit',t:'word',k:'long',p:2,lv:2,make(){const W=R(4,12),k=R(3,10),m=R(500,800)/100,dd=R(150,400)/100,hm=r6(m-dd);if(hm<=1)return null;const T=r6(W*m+(W+k)*hm);
  return {stem:`At a fruit stall, there were ${k} more honeydews than watermelons. Each watermelon weighed ${fmtN(m)} kg, which was ${fmtN(dd)} kg heavier than each honeydew. The total mass of the fruits was ${fmtN(T)} kg.`,parts:[hwNum(W+k,{q:'How many honeydews were there?',marks:3,traps:[[W,'That is the number of watermelons. There were '+k+' more honeydews.'],[Math.round(T/(m+hm)),'Take away the extra honeydews first.']],work:[`Each honeydew: ${fmtN(m)} − ${fmtN(dd)} = ${fmtN(hm)} kg`,`Extra ${k} honeydews: ${k} × ${fmtN(hm)} = ${fmtN(r6(k*hm))} kg. Left: ${fmtN(T)} − ${fmtN(r6(k*hm))} = ${fmtN(r6(T-k*hm))} kg`,`Pairs: ${fmtN(r6(T-k*hm))} ÷ ${fmtN(r6(m+hm))} = ${W}, so honeydews = ${W} + ${k} = <b>${W+k}</b>`],hint:'Put the extra honeydews aside. The rest come in pairs.'})]}}});

/* ===================== RATIO AND AVERAGE ===================== */
hw({id:'ra-avg',t:'ratio',k:['mcq1','saq'],p:1,lv:1,make(k){if(Math.random()<.5){const n=R(3,6),a=R(12,40),T=n*a;return {stem:`The total marks scored by ${n} pupils is ${T}. What is their average mark?`,parts:[hwAns(k,a,{int:true,traps:[[T*n,'Average = total ÷ number of pupils.'],[T-n,'Divide, do not subtract.']],work:[`Average = ${T} ÷ ${n} = <b>${a}</b>`],hint:'Average = total ÷ how many.'})]}}
  const n=R(3,5),a=R(30,60),b=a+R(2,8),need=b*(n+1)-a*n;return {stem:`${hwN()[0]} scored an average of ${a} points in ${n} games. How many points must be scored in the next game to raise the average to ${b} points?`,parts:[hwAns(k,need,{int:true,traps:[[b,'The new game must also make up for the earlier games being below '+b+'.'],[b+(b-a),'Each of the '+n+' earlier games was '+(b-a)+' below the new average.']],work:[`Total so far: ${a} × ${n} = ${a*n}`,`Total needed: ${b} × ${n+1} = ${b*(n+1)}`,`${b*(n+1)} − ${a*n} = <b>${need}</b>`],hint:'Work with totals, not averages.'})]}}});
hw({id:'ra-ratio',t:'ratio',k:['saq','mcq2'],p:1,lv:2,make(k){const a=R(2,5),b=R(1,4),u=R(5,30),g=R(10,80),N=(a+b)*u+g;if(gcd(a,b)>1||a===b)return null;const v=b*u,[c1,c2]=pick([['red','blue'],['boys','girls'],['chicken','fish']]);
  return {stem:`There are ${N} marbles in a box. The ratio of red marbles to blue marbles is ${a} : ${b}. The other ${g} marbles are green. How many blue marbles are there?`,parts:[hwAns(k,v,{int:true,traps:[[N/(a+b)*b,'Take away the green marbles first.'],[a*u,'That is the number of red marbles.'],[(N-g)/b,'There are '+(a+b)+' units of red and blue together.']],work:[`Red + blue: ${N} − ${g} = ${N-g}`,`${a} + ${b} = ${a+b} units = ${N-g}, 1 unit = ${u}`,`Blue: ${b} × ${u} = <b>${v}</b>`],hint:'The ratio is only about the red and blue marbles.'})],
    cal:{lines:[`${a} + ${b} = ${a+b} units = ${N}`,`1 unit = ${fmtN(r6(N/(a+b)))}`],bad:0,why:`The ${g} green marbles are not part of the ratio. Take them away first.`,fix:`${a+b} units = ${N} − ${g} = ${N-g}`}}}});
hw({id:'ra-group',t:'ratio',k:'long',p:2,lv:2,make(){const p1=pick([5,6,7,8]),p2=pick([2,2.5,3]),r1=1,r2=R(3,8),grp=R(8,25),T=r6(grp*(p1*r1+p2*r2)),nm=hwN()[0];
  return {stem:`${nm} sold pies at ${$m(p1)} each and muffins at ${$m(p2)} each. The ratio of pies sold to muffins sold was ${r1} : ${r2}. ${nm} collected ${$m(T)} altogether.`,parts:[hwNum(grp,{q:'How many pies were sold?',marks:2,traps:[[Math.round(T/(p1+p2)),`Each group has 1 pie and ${r2} muffins, not 1 of each.`],[grp*r2,'That is the number of muffins.']],work:[`1 group = 1 pie + ${r2} muffins = ${$m(p1)} + ${r2} × ${$m(p2)} = ${$m(p1+r2*p2)}`,`${$m(T)} ÷ ${$m(p1+r2*p2)} = ${grp} groups → <b>${grp}</b> pies`],hint:'Make a group that matches the ratio.'}),
    hwNum(r6(grp*r2*p2),{q:'How much was collected from the muffins?',marks:1,pre:'$',traps:[],work:[`${grp*r2} muffins × ${$m(p2)} = <b>${$m(grp*r2*p2)}</b>`]})]}}});
hw({id:'ra-avg2',t:'ratio',k:'long',p:2,lv:3,make(){const n=R(3,9),m=R(2,4),a=R(30,60),c=a+R(5,20),b=c+n*(c-a)/m;if(!hwInt(b))return null;
  return {stem:`${hwN()[0]} bought some pairs of shoes at an average price of ${$m(a)}. Then ${m} more pairs were bought at ${$m(b)} each, and the average price became ${$m(c)}.`,parts:[hwNum(n+m,{q:'How many pairs of shoes were bought altogether?',marks:3,traps:[[n,`That is the number bought at first. Add the ${m} new pairs.`]],work:[`Each new pair is ${$m(b)} − ${$m(c)} = ${$m(b-c)} above the new average: ${m} × ${$m(b-c)} = ${$m(m*(b-c))} extra.`,`Each earlier pair is ${$m(c-a)} below the new average, so ${$m(m*(b-c))} ÷ ${$m(c-a)} = ${n} pairs at first.`,`${n} + ${m} = <b>${n+m}</b>`],hint:'Compare each price with the NEW average.'}),
    hwNum(c*(n+m),{q:'How much was spent on all the shoes?',marks:1,pre:'$',traps:[[a*n+b,'Each new pair costs '+$m(b)+'.']],work:[`${$m(c)} × ${n+m} = <b>${$m(c*(n+m))}</b>`]})]}}});
